# Check if the WebSocket server (not hwebserver) is running
# This is the one the stdio bridge connects to
import gc
servers = []
for obj in gc.get_objects():
    t = type(obj).__name__
    if 'SynapseServer' in t or 'WebSocketServer' in t:
        servers.append({
            'class': t,
            'port': getattr(obj, '_port', getattr(obj, '_actual_port', 'unknown')),
            'running': getattr(obj, '_running', 'unknown'),
        })
result = {'servers': servers[:5], 'count': len(servers)}

# Lightweight: just check if hwebserver_adapter was ever imported and its state
import sys
result = {}
mod = sys.modules.get('synapse.server.hwebserver_adapter')
if mod:
    result['adapter_running'] = getattr(mod, '_running', False)
    result['adapter_port'] = getattr(mod, '_port', 0)
else:
    result['adapter_loaded'] = False

# Check the websocket module instead
ws_mod = sys.modules.get('synapse.server.websocket')
if ws_mod:
    result['websocket_loaded'] = True
else:
    result['websocket_loaded'] = False
